import React, { useEffect, useRef, useState } from 'react';

type LogoProps = {
  src?: string;
  height?: number;
  width?: number;
  threshold?: number; // 0-255, higher removes more near-white
  className?: string;
  alt?: string;
};

// Client-side background remover: makes near-white pixels transparent
export default function Logo({
  src = '/logo.png',
  height = 32,
  width,
  threshold = 240,
  className,
  alt = 'لوگو',
}: LogoProps) {
  const [dataUrl, setDataUrl] = useState<string | null>(null);
  const [naturalSize, setNaturalSize] = useState<{ w: number; h: number } | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      const w = img.naturalWidth;
      const h = img.naturalHeight;
      setNaturalSize({ w, h });
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, w, h);
      const data = imageData.data;
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        // If close to white, make transparent
        if (r >= threshold && g >= threshold && b >= threshold) {
          data[i + 3] = 0;
        }
      }
      ctx.putImageData(imageData, 0, 0);
      const url = canvas.toDataURL('image/png');
      setDataUrl(url);
      canvasRef.current = canvas;
    };
    img.onerror = () => {
      // Fallback: just use original src
      setDataUrl(null);
    };
    img.src = src;
  }, [src, threshold]);

  const computedStyle: React.CSSProperties = {
    height,
    width,
    display: 'inline-block',
    objectFit: 'contain',
  };

  // If we have a processed data URL, use it; otherwise use raw src
  const finalSrc = dataUrl ?? src;

  return (
    <img
      src={finalSrc}
      alt={alt}
      className={className}
      style={computedStyle}
      loading="eager"
    />
  );
}
export const ThemeToggle: React.FC = () => {
  const [theme, setTheme] = React.useState<string>(() => localStorage.getItem('theme') || 'light');
  React.useEffect(() => {
    document.body.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);
  return (
    <button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="login-btn" style={{ marginInlineEnd: 8 }}>
      {theme === 'dark' ? 'تم روشن' : 'تم تاریک'}
    </button>
  );
};
